window.STUDY_DATA = [{"topic": "cardio", "title": "Cardiovascular — High-Yield Review", "sections": [{"heading": "Hypertension first-line agents", "bullets": ["ACEI, ARB, thiazide/thiazide-like diuretic, or long-acting CCB — all first-line", "Diabetes + hypertension or CKD with albuminuria: ACEI or ARB preferred", "Black patients: CCB or thiazide often preferred over ACEI/ARB monotherapy", "Never combine ACEI + ARB (or + direct renin inhibitor) — hyperkalemia/AKI risk", "Uncomplicated HTN target: <140/90; diabetes target: <130/80 per Diabetes Canada"]}, {"heading": "Heart failure — the 4 pillars (HFrEF)", "bullets": ["ARNI (or ACEI/ARB) + Beta-blocker + MRA + SGLT2i = 4 pillars, start early and in parallel where possible", "Beta-blockers with HF mortality evidence: bisoprolol, carvedilol, metoprolol succinate (ER) ONLY", "SGLT2i (empagliflozin/dapagliflozin) benefit HF regardless of diabetes status", "Loop diuretics = symptom control only, no mortality benefit", "Wash out ACEI 36h before starting ARNI (sacubitril/valsartan) — angioedema risk if overlapped"]}, {"heading": "Lipid management", "bullets": ["High-intensity statin = atorvastatin 40-80mg or rosuvastatin 20-40mg (≥50% LDL reduction)", "Statin + high triglycerides not controlled: consider icosapent ethyl or fibrate add-on", "Statins contraindicated in pregnancy/breastfeeding and active liver disease", "Muscle pain + fever/dark urine = check CK, think rhabdomyolysis", "Simvastatin (unlike atorvastatin/rosuvastatin) has more CYP3A4 interactions — dose cap with amlodipine/diltiazem"]}, {"heading": "Anticoagulation & antiplatelets", "bullets": ["DOACs preferred over warfarin for non-valvular AFib (no routine monitoring)", "Warfarin still required for mechanical heart valves and moderate-severe mitral stenosis", "Apixaban dose reduction: ≥2 of [age ≥80, weight ≤60kg, SCr ≥133 µmol/L]", "DAPT (ASA + P2Y12 inhibitor) post-stent: typically 6-12 months, individualized to bleeding risk", "Warfarin target INR 2-3 (2.5-3.5 for mechanical mitral valve)"]}, {"heading": "Key interactions to know", "bullets": ["Amiodarone + warfarin → potentiates INR, reduce warfarin dose ~30-50%", "Amiodarone + digoxin → increases digoxin level, reduce digoxin dose", "Verapamil/diltiazem + beta-blocker → additive bradycardia/AV block, generally avoid combo", "Clopidogrel + omeprazole/esomeprazole → reduced antiplatelet activation, use pantoprazole instead", "NSAIDs blunt ACEI/ARB/diuretic effect and worsen renal function — 'triple whammy' with ACEI+diuretic+NSAID"]}, {"heading": "Monitoring parameters", "bullets": ["ACEI/ARB/ARNI: SCr and K+ at baseline and 1-2 weeks after start/titration", "Statins: baseline LFTs; CK only if symptomatic myopathy", "Digoxin: trough level 0.5-0.9 ng/mL for HF, plus renal function and electrolytes", "Amiodarone: TFTs, LFTs, chest X-ray/PFTs, eye exam at baseline and periodically", "Warfarin: INR regularly, more frequently at initiation or with dose/diet/drug changes"]}, {"heading": "Red flags / when to escalate", "bullets": ["Angioedema (ACEI/ARNI) → stop immediately, do not rechallenge with any ACEI", "Resting HR <50 bpm or symptomatic bradycardia on beta-blocker/digoxin → hold and reassess", "Rapid weight gain >2kg in a few days in HF patient → possible decompensation", "Signs of digoxin toxicity: nausea, visual halos, arrhythmia → check level, consider DigiFab if severe", "Unexplained severe muscle pain + dark urine on statin → check CK, think rhabdomyolysis"]}, {"heading": "Classic exam traps", "bullets": ["Metoprolol TARTRATE (IR) has no HFrEF mortality benefit — only the SUCCINATE (ER) salt does", "Amlodipine edema is NOT fluid overload — don't reflexively add a diuretic", "DOACs are NOT for mechanical valves or significant mitral stenosis — warfarin required", "Furosemide has sulfa-like structure — caution (not absolute contraindication) in sulfa allergy", "Spironolactone + ACEI/ARB = high hyperkalemia risk — always check K+ before and after starting"]}]}, {"topic": "endo", "title": "Endocrine & Diabetes — High-Yield Review", "sections": [{"heading": "T2DM drug therapy — where each agent fits", "bullets": ["Metformin = first-line for essentially everyone with T2DM (unless eGFR <30 or other contraindication)", "Established ASCVD, HF, or CKD → add SGLT2i or GLP-1 RA with proven benefit, regardless of A1C", "SGLT2i: cardiorenal protection, weight loss, euglycemic DKA risk, genital infections", "GLP-1 RA: strong A1C + weight benefit, GI side effects, avoid in personal/family MTC or MEN2 history", "Sulfonylureas/TZD: effective but weight gain + hypoglycemia (SU) or HF risk (TZD) — lower priority now"]}, {"heading": "Insulin basics", "bullets": ["Basal (glargine, detemir): once-daily, peakless, covers background needs", "Rapid-acting (aspart, lispro): mealtime coverage, given just before/with meals", "Never mix glargine with other insulins in the same syringe", "Insulin = high-alert drug — always double check units, insulin type, and pen vs. vial", "Hypoglycemia treatment: 15g fast-acting carbs, recheck glucose in 15 min ('15-15 rule')"]}, {"heading": "Guideline targets & numbers", "bullets": ["A1C target for most adults with T2DM: ≤7.0%", "Fasting/preprandial glucose target: 4-7 mmol/L; 2h postprandial: 5-10 mmol/L", "BP target in diabetes: <130/80", "LDL target in diabetes with additional risk factors: often <2.0 mmol/L or ≥50% reduction — statin usually indicated", "Dose-reduce metformin at eGFR 30-45; generally avoid/stop below eGFR 30"]}, {"heading": "Thyroid & bone essentials", "bullets": ["Levothyroxine: take on empty stomach, separate from calcium/iron/PPIs by ≥4 hours", "Recheck TSH 6-8 weeks after any levothyroxine dose change", "Methimazole preferred over PTU except 1st trimester pregnancy or thyroid storm", "Bisphosphonates: take fasting with full glass of water, stay upright 30-60 min after", "Bisphosphonate rare risks: osteonecrosis of jaw, atypical femur fracture — dental work before starting ideally"]}, {"heading": "Major contraindications & cautions", "bullets": ["Metformin: avoid if eGFR <30, acute illness/dehydration, contrast dye (hold around procedure)", "GLP-1 RA/exenatide-class: avoid with personal/family history of medullary thyroid cancer or MEN2", "TZDs (pioglitazone): avoid in NYHA III-IV heart failure", "SGLT2i: hold during 'sick days' (vomiting, not eating/drinking, acute illness, pre-surgery) — DKA risk", "Sulfonylureas: use cautiously in elderly/renal impairment — higher hypoglycemia risk"]}, {"heading": "Key interactions to know", "bullets": ["Levothyroxine + calcium/iron/PPI/antacids → reduced absorption, separate dosing", "Insulin/sulfonylurea + GLP-1 RA or SGLT2i → additive hypoglycemia risk, may need dose reduction", "Corticosteroids (prednisone) → cause/worsen hyperglycemia, may need diabetes med adjustment", "Beta-blockers → can mask adrenergic hypoglycemia symptoms (tachycardia) but sweating persists", "Fluoroquinolones → can cause both hyper- and hypoglycemia in patients on diabetes meds"]}, {"heading": "Monitoring parameters", "bullets": ["Metformin: renal function (eGFR) at least annually, B12 periodically with long-term use", "Levothyroxine: TSH 6-8 weeks post dose change, then periodically", "SGLT2i/GLP-1: renal function, volume status; watch for DKA symptoms even with normal glucose", "Sulfonylureas/insulin: home blood glucose monitoring, hypoglycemia awareness", "Long-term corticosteroids: blood glucose, BP, bone density"]}, {"heading": "Classic exam traps", "bullets": ["Euglycemic DKA can occur on SGLT2i even with near-normal blood glucose — don't rule out DKA just because glucose looks fine", "Metformin does NOT cause hypoglycemia on its own — think of other agents if a patient reports lows", "Rybelsus (oral semaglutide) needs empty stomach + minimal water + wait 30 min — very different from injectable Ozempic", "Methimazole is teratogenic in 1st trimester — PTU is the pregnancy-preferred antithyroid in that window", "'Sick day rules' apply to metformin AND SGLT2i — hold both during acute illness/dehydration/vomiting"]}]}, {"topic": "resp", "title": "Respiratory — High-Yield Review", "sections": [{"heading": "Asthma: controller ladder (GINA)", "bullets": ["Track 1 (preferred): as-needed low-dose ICS-formoterol at every step, even mild asthma", "Step 1-2: as-needed low-dose ICS-formoterol (or low-dose ICS + SABA if track 2)", "Step 3: low-dose ICS-formoterol maintenance + as-needed reliever (MART/SMART)", "Step 4: medium-dose ICS-formoterol MART", "Step 5: add LAMA, refer for biologics (severe eosinophilic/allergic asthma)", "SABA-only reliever therapy is now discouraged — increases exacerbation risk vs ICS-containing reliever"]}, {"heading": "COPD: drug choice by GOLD group", "bullets": ["Group A (low symptoms/risk): a bronchodilator (SABA/SAMA or LABA/LAMA)", "Group B (more symptoms, low risk): LABA or LAMA — LAMA often preferred", "Group E (high exacerbation risk): LABA+LAMA; add ICS if eos ≥300 cells/µL or history of asthma overlap", "ICS in COPD only if frequent exacerbations + high eosinophils — NOT first-line like in asthma", "Smoking cessation is the single intervention that changes disease trajectory"]}, {"heading": "Inhaler technique & spacers", "bullets": ["Spacers reduce oropharyngeal deposition — cuts thrush/dysphonia risk with ICS", "Rinse and spit after every ICS dose (thrush, hoarseness prevention)", "HandiHaler capsules are inhaled, never swallowed", "Formoterol has fast onset (~1-3 min) — enables MART; salmeterol does NOT (slow onset, never for rescue)"]}, {"heading": "Numbers & thresholds that get tested", "bullets": ["SABA overuse red flag: >1 canister/month or >2 canisters/year", "Topical decongestant (oxymetazoline): max 3 consecutive days — rebound congestion after", "Blood eosinophils ≥300 cells/µL favours adding ICS in COPD", "LABA monotherapy in asthma = boxed warning; always pair with ICS"]}, {"heading": "Key contraindications & cautions", "bullets": ["LAMA (tiotropium): caution in narrow-angle glaucoma, BPH/urinary retention", "Pseudoephedrine: avoid in uncontrolled HTN, CVD, and with MAOIs (hypertensive crisis)", "Montelukast: boxed warning for neuropsychiatric effects (agitation, suicidality)", "Bupropion (smoking cessation): contraindicated in seizure disorder, eating disorder"]}, {"heading": "Smoking cessation pharmacotherapy", "bullets": ["Varenicline = most effective single agent; start 1 week pre-quit, course ~12 wks", "Combination NRT (patch + gum/lozenge) beats any single NRT form alone", "NRT is safe in cardiovascular disease — classic exam trap (it's NOT contraindicated post-MI)", "Bupropion and varenicline both start 1-2 weeks before the quit date"]}, {"heading": "Monitoring parameters", "bullets": ["ICS long-term: growth (kids), bone density, cataracts with high-dose chronic use", "Roflumilast: monitor weight (significant weight loss risk), mood/psychiatric symptoms", "Varenicline/bupropion: monitor mood and behaviour changes", "Spirometry (FEV1) tracks COPD severity and guides GOLD grouping"]}, {"heading": "Exam traps to remember", "bullets": ["LABA alone in asthma = dangerous; always with ICS (never true for COPD)", "Oxymetazoline >3 days → rhinitis medicamentosa, worse congestion", "First-gen antihistamines (diphenhydramine) — avoid in elderly (Beers Criteria, anticholinergic/fall risk)", "Pseudoephedrine is behind-the-counter due to methamphetamine precursor status", "Formoterol vs salmeterol onset difference is the reason only formoterol combos are used in SMART/MART"]}]}, {"topic": "cns", "title": "Neurology & Psychiatry — High-Yield Review", "sections": [{"heading": "Antidepressants: first-line & timing", "bullets": ["SSRIs are first-line for MDD and most anxiety disorders", "Full effect takes 4-6 weeks; side effects (GI, anxiety) often appear first and fade", "All antidepressants carry boxed warning: increased suicidality risk <25 years old, esp. first weeks", "Never combine SSRI/SNRI with MAOIs — 14-day washout required (serotonin syndrome risk)", "Venlafaxine/paroxetine have the worst discontinuation syndromes — taper slowly"]}, {"heading": "Antipsychotics: typical vs atypical", "bullets": ["Atypicals (quetiapine, risperidone, olanzapine) = lower EPS, higher metabolic risk (weight gain, dyslipidemia, hyperglycemia)", "Typicals, esp. high-potency (haloperidol) = high EPS/tardive dyskinesia, low sedation/anticholinergic burden", "Risperidone stands out among atypicals for dose-dependent EPS and hyperprolactinemia", "All antipsychotics: boxed warning for increased mortality in elderly dementia-related psychosis", "Neuroleptic malignant syndrome = fever, rigidity, autonomic instability, altered mental status — emergency"]}, {"heading": "Mood stabilizers: monitoring essentials", "bullets": ["Lithium target trough 0.6-1.2 mmol/L, drawn 12h post-dose; toxicity = coarse tremor, ataxia, confusion", "Lithium raised by NSAIDs, ACEi/ARBs, thiazides — classic interaction", "Valproate: boxed warnings — teratogenicity, hepatotoxicity, pancreatitis; needs contraception counselling", "Carbamazepine: boxed warnings — SJS/TEN (check HLA-B*1502 in Asian ancestry), aplastic anemia/agranulocytosis", "Lamotrigine: slow titration mandatory — rapid titration or valproate co-administration raises SJS/TEN risk"]}, {"heading": "Parkinson's disease pharmacology", "bullets": ["Levodopa/carbidopa = most effective for motor symptoms but causes long-term dyskinesias/'wearing off'", "Never stop levodopa abruptly — risk of parkinsonism-hyperpyrexia crisis (like NMS)", "Dopamine agonists (pramipexole): watch for impulse control disorders (gambling, hypersexuality) and sudden sleep attacks", "High-protein meals can reduce levodopa absorption — timing matters as disease advances", "Non-selective MAOIs contraindicated with levodopa (hypertensive crisis)"]}, {"heading": "Cholinesterase inhibitors (Alzheimer's)", "bullets": ["Donepezil provides modest SYMPTOMATIC benefit only — not disease-modifying", "GI side effects (nausea, diarrhea) are dose-related, most common on titration", "Avoid combining with anticholinergic drugs — opposing mechanisms, common prescribing-cascade error", "Caution/avoid in bradycardia or conduction disease without a pacemaker"]}, {"heading": "Benzodiazepines, Z-drugs & triptans", "bullets": ["Lorazepam (LOT drugs: Lorazepam/Oxazepam/Temazepam) — no active metabolites, safer in hepatic impairment/elderly", "Benzo + opioid combo = boxed warning for fatal respiratory depression", "Z-drugs (zopiclone) — short-term use only; Beers Criteria flags them same as benzos for elderly falls/cognition", "Triptans (sumatriptan) contraindicated in CVD, uncontrolled HTN, stroke/TIA history — vasoconstriction risk", "Triptan + triptan/ergot within 24h = contraindicated; limit use <10 days/month to avoid medication-overuse headache"]}, {"heading": "Key interactions to know", "bullets": ["Serotonin syndrome: SSRI/SNRI + MAOI, triptan, tramadol, or another serotonergic agent", "Lithium levels raised by NSAIDs, ACEi/ARBs, thiazide diuretics", "Valproate inhibits lamotrigine metabolism — requires lower/slower lamotrigine titration", "Carbamazepine (CYP3A4 inducer) reduces efficacy of hormonal contraceptives and warfarin", "Levodopa + non-selective MAOIs = hypertensive crisis"]}, {"heading": "Red flags requiring urgent action", "bullets": ["Fever + rigidity + autonomic instability + confusion → suspect NMS, stop antipsychotic, seek emergency care", "New rash on lamotrigine or carbamazepine → hold drug, assess for SJS/TEN immediately", "Worsening mood, agitation, or suicidal ideation on any antidepressant, esp. in youth → urgent reassessment", "Coarse tremor, ataxia, confusion on lithium → suspect toxicity, check level, hold dose", "Abrupt levodopa discontinuation with fever/rigidity → parkinsonism-hyperpyrexia crisis, emergency"]}, {"heading": "Classic exam-trap pearls", "bullets": ["Risperidone is the atypical most associated with hyperprolactinemia/EPS — don't lump it with quetiapine/olanzapine", "Lithium toxicity is precipitated by dehydration/low-sodium diets, not just overdose", "Valproate needs contraception counselling in anyone of childbearing potential — always flag", "NRT is safe post-MI — smoking itself is the danger, not the nicotine patch", "Donepezil + anticholinergic OTC sleep aid = therapeutic antagonism, a common prescribing-cascade trap"]}]}, {"topic": "infd", "title": "Infectious Disease — High-Yield Review", "sections": [{"heading": "Empiric Therapy by Syndrome", "bullets": ["Uncomplicated cystitis: nitrofurantoin x5d, TMP-SMX x3d, or fosfomycin single dose (first-line)", "Pyelonephritis: fluoroquinolone or ceftriaxone; avoid nitrofurantoin (no tissue penetration)", "CAP outpatient, healthy: amoxicillin or doxycycline or macrolide", "CAP with comorbidities: amoxicillin-clavulanate + macrolide, or respiratory fluoroquinolone", "Cellulitis (non-purulent): cephalexin or cloxacillin; add MRSA coverage (TMP-SMX/doxycycline) if purulent/abscess", "Animal/human bite: amoxicillin-clavulanate (covers Pasteurella + anaerobes)"]}, {"heading": "Penicillin Allergy Pearls", "bullets": ["True IgE-mediated allergy: avoid all penicillins; cephalosporin cross-reactivity is low (~1-2%) but caution with shared side-chain agents", "Ampicillin/amoxicillin rash + mononucleosis is NOT a true allergy — common exam trap", "Severe reactions (anaphylaxis, SJS/TEN) = avoid entire beta-lactam class including cephalosporins/carbapenems"]}, {"heading": "Key Contraindications & Renal Cutoffs", "bullets": ["Nitrofurantoin: avoid CrCl <30 mL/min (ineffective + toxic)", "TMP-SMX: avoid near-term pregnancy (kernicterus); avoid 1st trimester (neural tube defects)", "Fluoroquinolones: boxed warning tendon rupture, aortic dissection, avoid first-line in uncomplicated cystitis", "Doxycycline/tetracyclines: avoid in pregnancy and children <8 years (teeth/bone)", "Ceftriaxone: no renal adjustment needed (biliary excretion) — do not give with IV calcium in neonates"]}, {"heading": "Classic Drug Interactions", "bullets": ["Metronidazole + alcohol = disulfiram-like reaction", "Macrolides/azoles = CYP3A4 inhibition → statin toxicity (hold simvastatin/lovastatin with clarithromycin)", "Fluoroquinolones/tetracyclines + divalent cations (Ca, Mg, Fe, Al, Zn) = chelation, reduced absorption — separate 2-6h", "TMP-SMX + warfarin = increased INR (CYP2C9 inhibition)", "Clarithromycin + colchicine (renal/hepatic impairment) = contraindicated, fatal toxicity risk"]}, {"heading": "Monitoring Parameters", "bullets": ["Vancomycin: AUC/MIC or trough levels, SCr (nephrotoxicity), hearing (ototoxicity)", "Aminoglycosides: peak/trough levels, SCr, hearing", "Long-term nitrofurantoin: pulmonary function/symptoms", "Fluoroquinolones/macrolides: QTc if other QT-prolonging drugs on board"]}, {"heading": "Red Flags — Escalate Care", "bullets": ["Rash + fever + mucosal involvement = possible SJS/TEN, stop drug immediately", "Sudden tendon pain/swelling on fluoroquinolone = stop drug, avoid activity", "Severe/bloody diarrhea on any antibiotic = think C. difficile, consider oral vancomycin or fidaxomicin", "New confusion + antibiotic in elderly = consider drug toxicity/accumulation (renal dosing)"]}, {"heading": "Antifungals & Antivirals Quick Hits", "bullets": ["Fluconazole: CYP inhibitor, single 150mg dose for uncomplicated vaginal candidiasis", "Oseltamivir: start within 48h of flu symptom onset, renal dose adjust <60 mL/min", "Valacyclovir: start within 72h of zoster rash, hydrate well (crystalline nephropathy risk)"]}, {"heading": "Exam-Trap Pearls", "bullets": ["Nitrofurantoin turns urine brown — harmless, not a reason to stop", "Metronidazole causes metallic taste — expected, not an allergy", "Ceftriaxone is the ONE cephalosporin that does NOT need renal dose adjustment", "A macrolide rash reaction during mono is expected with ampicillin/amoxicillin, not true allergy", "'Culture and sensitivity pending' + sick patient = start empiric broad coverage, narrow later (de-escalation)"]}]}, {"topic": "renal", "title": "Renal & Electrolytes — High-Yield Review", "sections": [{"heading": "Diuretics by Class", "bullets": ["Loop (furosemide, bumetanide): works even at low GFR, causes hypoK/hypoMg/hypoNa/metabolic alkalosis, ototoxicity risk if rapid IV/high dose", "Thiazide (HCTZ, chlorthalidone): loses efficacy at eGFR <30, causes hypoK/hypoNa/hyperCa/hyperuricemia/hyperglycemia", "Potassium-sparing (spironolactone, eplerenone, amiloride): risk of hyperkalemia, avoid/caution with ACEi/ARB or eGFR <30", "Spironolactone causes gynecomastia (antiandrogen effect) — eplerenone is selective alternative"]}, {"heading": "Hyperkalemia Management Ladder", "bullets": ["Stabilize cardiac membrane: IV calcium gluconate (does not lower K, protects heart)", "Shift K+ intracellularly: insulin + glucose, salbutamol (fast, temporary)", "Remove K+ from body: patiromer (onset ~7h) or sodium zirconium cyclosilicate (onset ~1h) for chronic; dialysis for emergent/refractory", "Sodium bicarbonate can help shift K+ intracellularly if concurrent metabolic acidosis present", "Potassium binders are NOT for acute life-threatening hyperkalemia as monotherapy — too slow"]}, {"heading": "CKD-MBD (Mineral Bone Disease) Management", "bullets": ["Phosphate binders (sevelamer, calcium carbonate) must be taken WITH meals to bind dietary phosphate", "Non-calcium binders (sevelamer) preferred if vascular calcification risk or hypercalcemia present", "Calcitriol (active vitamin D) needed because failing kidneys lose 1-alpha-hydroxylase — suppresses PTH, raises Ca/phosphate", "Cinacalcet (calcimimetic) LOWERS calcium while suppressing PTH — opposite calcium effect vs. vitamin D analogs", "Target: control PTH without over-suppressing (risk of adynamic bone disease)"]}, {"heading": "Renal Dose Adjustment — Classic Examples", "bullets": ["Nitrofurantoin: avoid CrCl <30", "Gabapentin: significant reduction needed, accumulation causes myoclonus/encephalopathy in renal failure", "Digoxin: reduce dose, narrow therapeutic index (target 0.5-0.9 ng/mL), toxicity worsened by hypoK/hypoMg/hyperCa", "Enoxaparin: dose reduce CrCl <30, consider anti-Xa monitoring", "Metformin: avoid/reduce per eGFR thresholds (contraindicated <30, caution 30-45)"]}, {"heading": "Anemia of CKD (ESAs)", "bullets": ["Epoetin alfa / darbepoetin alfa stimulate erythropoiesis — boxed warning for CV death/MI/stroke/VTE if Hgb target too high", "Target Hgb 100-115 g/L; avoid normalizing to >130 g/L", "Correct iron deficiency (ferritin/TSAT) BEFORE/DURING ESA therapy — iron deficiency blunts response", "Uncontrolled hypertension is a contraindication until BP controlled"]}, {"heading": "Acid-Base & Bicarbonate", "bullets": ["KDIGO recommends oral sodium bicarbonate if serum bicarb persistently <22 mmol/L to slow CKD progression", "Watch for volume overload/hypertension worsening from sodium load", "Metabolic acidosis in CKD relates to reduced ammoniagenesis and acid excretion as nephrons are lost"]}, {"heading": "Monitoring Parameters", "bullets": ["Diuretics: electrolytes (K, Na, Mg), renal function, blood pressure, daily weights", "ESAs: Hgb (q2-4 weeks during titration), iron studies, blood pressure", "Phosphate binders/vitamin D/cinacalcet: serum calcium, phosphate, PTH regularly", "Potassium binders: serum potassium and magnesium (patiromer can cause hypomagnesemia)"]}, {"heading": "Exam-Trap Pearls", "bullets": ["Thiazides RAISE calcium (favor them in patients with osteoporosis/hypercalciuric stones); loops LOWER calcium", "Patiromer/SZC are for CHRONIC hyperkalemia — not fast enough for a crashing hyperkalemic emergency", "Ceftriaxone needs no renal adjustment (biliary clearance) — contrast with nitrofurantoin (avoid <30) as opposite examples", "Spironolactone + ACEi/ARB + K supplement = classic triple-hit hyperkalemia combination to flag", "Cinacalcet lowers calcium; calcitriol raises calcium — easy to mix up on exam, both lower PTH"]}]}, {"topic": "gi", "title": "GI & Hepatic — High-Yield Review", "sections": [{"heading": "GERD / Acid Suppression Ladder", "bullets": ["Lifestyle first: weight loss, avoid trigger foods, elevate head of bed, avoid late meals", "Step-up: antacids/OTC H2RA → PPI (most effective for erosive esophagitis)", "PPIs taken 30-60 min before breakfast for max efficacy — needs active proton pumps", "Long-term PPI risks: B12/Mg deficiency, fracture risk, C. diff, rebound hyperacidity on stopping", "Alarm features requiring referral/endoscopy: dysphagia, weight loss, GI bleed, age >60 new onset"]}, {"heading": "H. pylori Eradication", "bullets": ["Standard triple: PPI + clarithromycin + amoxicillin (or metronidazole if PCN-allergic) x 7-14 days", "Quadruple (bismuth): PPI + bismuth subsalicylate + metronidazole + tetracycline — preferred if clarithromycin resistance/prior macrolide exposure", "Confirm eradication with urea breath test or stool antigen ≥4 weeks post-therapy, off PPI ≥1-2 weeks before test", "Test-and-treat approach for uninvestigated dyspepsia in younger patients without alarm features"]}, {"heading": "Antiemetics — Match Mechanism to Cause", "bullets": ["Ondansetron (5-HT3 antagonist): chemo/post-op nausea; watch QT prolongation", "Metoclopramide (D2 antagonist/prokinetic): gastroparesis, limit to <12 weeks (EPS/tardive dyskinesia boxed warning)", "Domperidone: peripheral D2 antagonist, less EPS than metoclopramide but QT/cardiac risk — avoid in cardiac disease, age >60 caution", "Dimenhydrinate: motion sickness, sedating, anticholinergic — caution in elderly/glaucoma/BPH"]}, {"heading": "Laxative Selection", "bullets": ["PEG 3350 (osmotic): first-line for chronic constipation, well tolerated, safe long-term", "Docusate: stool softener, prevention/prophylaxis only — weak evidence to treat established constipation", "Senna (stimulant): onset 6-12h, dose at bedtime; first-line add-on for opioid-induced constipation", "Lactulose: constipation AND hepatic encephalopathy (titrate to 2-3 soft stools/day) — expect flatulence"]}, {"heading": "Antidiarrheals — Red Flags", "bullets": ["Loperamide: avoid in bloody diarrhea/fever (invasive infection risk, toxic megacolon)", "High-dose/misuse loperamide → QT prolongation, torsades — Health Canada safety warning", "Bismuth subsalicylate: causes harmless black stool/tongue; avoid in children with viral illness (Reye's), ASA allergy"]}, {"heading": "IBD (Ulcerative Colitis) Basics", "bullets": ["5-ASA (mesalamine) first-line for mild-moderate UC; formulation matched to disease location (topical for distal, oral+rectal for pancolitis)", "Sulfasalazine = sulfapyridine + 5-ASA; more side effects, give folic acid supplementation", "Monitor renal function with mesalamine (rare nephrotoxicity)", "Combination oral + rectal therapy > oral alone for distal UC"]}, {"heading": "Hepatic Disease Pearls", "bullets": ["Lactulose titrated to 2-3 soft BMs/day is mainstay for hepatic encephalopathy (traps ammonia as NH4+)", "Ursodiol: dissolves radiolucent cholesterol gallstones only (not pigment stones); first-line for primary biliary cholangitis", "Acetaminophen max dose lowered (often ≤2g/day) in significant liver disease — avoid NSAIDs (bleeding/renal risk in cirrhosis with varices/ascites)"]}, {"heading": "Classic Exam Traps", "bullets": ["Ranitidine was withdrawn in Canada (NDMA) — famotidine is the H2RA now used", "Omeprazole/esomeprazole (CYP2C19 inhibitors) reduce clopidogrel activation — use pantoprazole if PPI needed with clopidogrel", "Metoclopramide EPS risk means therapy is capped at ~12 weeks", "Docusate alone is NOT sufficient to treat established hard/impacted constipation"]}]}, {"topic": "pain", "title": "Pain & MSK — High-Yield Review", "sections": [{"heading": "WHO-Style Analgesic Ladder", "bullets": ["Step 1: non-opioid (acetaminophen, NSAID) +/- adjuvant", "Step 2: weak opioid (codeine, tramadol) + non-opioid", "Step 3: strong opioid (morphine, hydromorphone, fentanyl) + non-opioid", "Acetaminophen is first-line for OA pain given favourable safety profile; NSAIDs added/used for inflammatory component"]}, {"heading": "Acetaminophen Safety", "bullets": ["Max ~4 g/day healthy adults; consider ≤3 g/day chronic use or hepatic risk factors, ≤2 g/day significant liver disease", "Watch for hidden acetaminophen in combo products (Tylenol #3, Tramacet, cold/flu remedies) — stacking risk", "Antidote for overdose: N-acetylcysteine (NAC) — time-critical, based on Rumack-Matthew nomogram"]}, {"heading": "NSAID Risk Triad", "bullets": ["GI: ulcer/bleed risk (COX-1 inhibition) — higher with age, prior ulcer, steroid/anticoagulant co-use", "Renal: avoid/caution in CKD, dehydration, 'triple whammy' (NSAID + ACEi/ARB + diuretic)", "CV: boxed warning class effect, even naproxen (lowest relative CV risk) — use lowest dose/shortest duration", "Timing with low-dose ASA: take ASA first; ibuprofen ≥30-60 min after (or ≥8h before) to preserve antiplatelet effect"]}, {"heading": "Opioid Equianalgesic & Safety Pearls", "bullets": ["Oral morphine : oral hydromorphone ≈ 5:1 (hydromorphone much more potent per mg)", "Fentanyl patch: ONLY for opioid-tolerant patients, never opioid-naive/acute pain — heat exposure raises absorption, risk of fatal overdose", "Codeine/tramadol: CYP2D6 prodrugs — contraindicated in children <12 and breastfeeding (ultrarapid metabolizer infant toxicity risk)", "Constipation does NOT develop tolerance — always co-prescribe a stimulant laxative prophylactically", "CDSA (controlled substances): no refills permitted on the original opioid prescription — new Rx required each time"]}, {"heading": "Gabapentinoids", "bullets": ["Gabapentin: renally eliminated, nonlinear/saturable absorption (why TID dosing), NOT a controlled substance federally", "Pregabalin: linear PK (BID dosing), IS subject to greater prescribing control/misuse potential than gabapentin", "Both: taper on discontinuation (withdrawal symptoms), caution combining with opioids (additive respiratory depression — Health Canada warning)"]}, {"heading": "RA / DMARD & Gout Essentials", "bullets": ["Methotrexate for RA is dosed ONCE WEEKLY — classic fatal dosing error if given daily; give folic acid on a different day", "MTX monitoring: CBC, LFTs, renal function; contraindicated in pregnancy (teratogenic), avoid alcohol and live vaccines", "Acute gout flare: colchicine (specific short loading-dose regimen), NSAID, or corticosteroid — NOT allopurinol", "Allopurinol: never start during an active flare; titrate slowly to urate target (<360, or <300 if tophi); flare prophylaxis (colchicine/NSAID) for first 3-6 months of initiation/titration", "Allopurinol + azathioprine/6-MP: major interaction — reduce thiopurine dose ~75% (xanthine oxidase inhibition)"]}, {"heading": "Muscle Relaxants", "bullets": ["Cyclobenzaprine: TCA-like structure, sedating/anticholinergic; short-term use only (~2-3 weeks); Beers List — caution in elderly", "Works centrally (CNS sedation), not a direct anti-inflammatory or peripheral muscle-acting agent", "Additive CNS depression with opioids/benzos/alcohol — counsel on driving and combination risk"]}, {"heading": "Classic Exam-Trap Pearls", "bullets": ["Methotrexate weekly (not daily) dosing error is one of the most tested pharmacist-verification scenarios", "Fentanyl patch in an opioid-naive patient = dangerous/contraindicated", "Allopurinol started during an acute flare can worsen/prolong it — start after flare resolves", "Hydromorphone potency (~5x oral morphine) — mixing up equianalgesic ratios is a common calculation trap", "NSAID + low-dose ASA timing matters for preserving cardioprotection — not just 'avoid combining'"]}]}, {"topic": "womens", "title": "Women's Health — High-Yield Review", "sections": [{"heading": "Combined Hormonal Contraceptives (CHC) — Absolute Contraindications", "bullets": ["Smoker AND age ≥35 → no estrogen, ever", "Migraine WITH aura at any age → CHC absolutely contraindicated (stroke risk)", "Migraine without aura + age ≥35 → caution/avoid estrogen", "History of VTE, or known thrombophilia → no estrogen", "Uncontrolled HTN (≥160/100), known CVD, or complicated valvular disease → avoid", "<21 days postpartum → avoid estrogen (VTE risk)", "Breast cancer (current) → avoid all hormonal contraception", "When estrogen is out, think progestin-only (POP, DMPA, implant, LNG-IUD)"]}, {"heading": "Progestin-Only Options — Quick Facts", "bullets": ["POP ('mini-pill') must be taken same time every day — >3h late = backup needed", "DMPA (Depo-Provera) injection q12wks — delayed return to fertility", "DMPA long-term use linked to reversible BMD loss — caution in adolescents", "LNG-IUD safe in migraine with aura and VTE history — progestin only, minimal systemic absorption", "Progestin-only methods generally safe in breastfeeding and smokers ≥35"]}, {"heading": "Pregnancy Drug Safety by Trimester", "bullets": ["1st trimester (weeks 3-8) = organogenesis → highest teratogen risk", "NSAIDs: avoid in 3rd trimester → premature ductus arteriosus closure", "ACE inhibitors/ARBs: contraindicated ALL trimesters → fetal renal damage, oligohydramnios", "Warfarin: teratogenic 1st trimester ('warfarin embryopathy') → switch to LMWH", "Isotretinoin: absolute contraindication → severe birth defects, requires 2 forms contraception", "Valproate: high neural tube defect risk → avoid if possible in pregnancy", "Live vaccines (MMR, varicella): contraindicated in pregnancy", "Folic acid 0.4-1mg/day preconception + 1st trimester prevents neural tube defects", "Methotrexate: contraindicated, teratogenic + abortifacient"]}, {"heading": "Breastfeeding Drug Safety", "bullets": ["Codeine contraindicated while breastfeeding — CYP2D6 ultra-rapid metabolizers → excess morphine → infant deaths reported", "Same CYP2D6 logic applies to tramadol — avoid in nursing mothers", "Preferred analgesics while breastfeeding: acetaminophen, ibuprofen", "Sulfonamides: avoid in newborns with G6PD deficiency or hyperbilirubinemia risk (kernicterus)", "Most antidepressants (sertraline preferred) considered compatible with breastfeeding", "Radioactive iodine and most chemotherapy: contraindicated during breastfeeding", "Exam trap: 'safe in pregnancy' does NOT automatically mean 'safe in breastfeeding' — assess separately"]}, {"heading": "Hormone Replacement Therapy (HRT) — Risk/Benefit", "bullets": ["Unopposed estrogen in a woman WITH a uterus → endometrial cancer risk — must add progestin", "Estrogen-only HRT is fine if patient has had a hysterectomy", "HRT increases risk: VTE, stroke, breast cancer (combined, long-term use)", "HRT benefits: reduces vasomotor symptoms (hot flashes), prevents osteoporosis", "Lowest effective dose, shortest duration = guiding principle", "Transdermal estrogen carries lower VTE risk than oral estrogen", "Same contraindications as CHC largely apply: current VTE, breast cancer, active liver disease"]}, {"heading": "Emergency Contraception (EC)", "bullets": ["Levonorgestrel (Plan B) — unscheduled/OTC, no age restriction, no ID or prescription needed in Canada", "Most effective within 72h, can be used up to 120h (efficacy declines with time)", "Ulipristal acetate (Ella) — effective up to 120h, more effective than LNG especially days 3-5", "Ulipristal: avoid concurrent progestin use ±5 days (antagonizes each other)", "Copper IUD = most effective EC option, effective up to 7 days post-coitus", "EC efficacy reduced in obesity (BMI >30) — copper IUD preferred if available", "EC does NOT interrupt an established pregnancy — it delays/prevents ovulation"]}, {"heading": "Key Guideline Thresholds to Memorize", "bullets": ["Age 35 + smoking = the classic CHC contraindication combo", "VTE risk with CHC use is highest in first year of use", "Migraine WITH aura = absolute; WITHOUT aura = relative (age/smoking dependent)", "BMI ≥30 → reduced efficacy of LNG EC and some contraceptive patches"]}, {"heading": "Classic Exam Traps", "bullets": ["Trap: assuming all hormonal contraceptives are contraindicated in migraine — only estrogen-containing ones are (POP/LNG-IUD OK)", "Trap: forgetting codeine's CYP2D6 breastfeeding danger — a favorite NAPLEX/PEBC scenario", "Trap: confusing EC scheduling — LNG is Unscheduled OTC, no prescription; don't say 'behind pharmacist counsel only' as a barrier", "Trap: thinking ACEi/ARB are only risky in 1st trimester — they are contraindicated throughout pregnancy", "Trap: assuming 'natural/herbal' products are automatically pregnancy-safe (e.g., some herbals are abortifacient/teratogenic)"]}]}, {"topic": "regs", "title": "Regulations & Law — High-Yield Review", "sections": [{"heading": "NAPRA Drug Schedules", "bullets": ["Schedule I: Prescription required, behind counter, pharmacist involvement mandatory (e.g., antibiotics, statins, antihypertensives)", "Schedule II: No prescription needed BUT must be purchased from pharmacist area (behind/near counter), pharmacist must be accessible (e.g., pseudoephedrine, some emergency contraception products, insulin syringes in some provinces)", "Schedule III: Self-selection allowed in pharmacy, but must be in area with pharmacist available for consultation (e.g., low-dose ibuprofen, hydrocortisone cream, loperamide)", "Unscheduled: Available outside pharmacy, no pharmacist required (e.g., most vitamins, plain acetaminophen in small pack sizes, basic cosmetics)", "Exam trap: Schedule II ≠ needs Rx — it means pharmacist must be involved/available, not that a prescription is required"]}, {"heading": "CDSA (Controlled Drugs and Substances Act) — Verbal Orders", "bullets": ["Verbal orders for narcotics/controlled drugs ARE permitted from a prescriber, but must be documented and often countersigned/confirmed", "Verbal orders NOT permitted for methadone in most provincial frameworks — written Rx required", "Refills on CDSA prescriptions: narcotics/controlled substances generally CANNOT be refilled without a new prescription (no 'refill authorized' like regular meds) — check provincial variance", "Benzodiazepines (targeted substances) — some refill flexibility exists provincially but stricter than regular Rx", "Transfers of controlled substance prescriptions between pharmacies: generally NOT permitted (unlike regular prescriptions) — provincial exceptions exist (e.g., one-time transfer in some provinces)"]}, {"heading": "CDSA — Loss, Theft & Reporting", "bullets": ["Loss or theft of controlled substances/narcotics MUST be reported to Health Canada (Office of Controlled Substances)", "Also report to local police AND provincial regulatory authority (College)", "Report required even for suspected loss/discrepancy, not just confirmed theft", "Inventory/perpetual records for narcotics must be maintained and reconciled regularly", "Destruction of controlled substances requires witnessed process and documentation per Health Canada requirements"]}, {"heading": "Privacy Law — Consent Exceptions", "bullets": ["General rule: patient consent required before disclosing personal health information", "Exception: disclosure required by law (e.g., reporting to public health, court order, coroner)", "Exception: imminent risk of serious harm to patient or identifiable third party (duty to warn)", "Exception: care/treatment purposes — sharing with other treating healthcare providers (circle of care) generally implied consent", "Exception: CDSA loss/theft reporting overrides normal privacy consent requirement", "Substitute decision-maker consent applies when patient lacks capacity (e.g., unconscious, dementia)", "Exam trap: 'circle of care' allows sharing WITHOUT explicit consent among direct treatment team, but NOT to family/employers without consent"]}, {"heading": "Pharmacist Prescribing — Scope Limits", "bullets": ["Pharmacists can NEVER independently prescribe controlled substances (narcotics, CDSA Schedule I drugs) — hard limit across all provinces", "Pharmacist prescribing authority varies by province: minor ailments, renewals/adaptations, smoking cessation, travel health are common scopes", "Prescribing for minor ailments excludes conditions with red flags (e.g., persistent symptoms, red-flag features) — must refer", "Adapting a prescription (dose/formulation change) ≠ initiating new independent prescribing — different authority level", "Exam trap: assuming expanded scope = can prescribe anything; controlled substances remain off-limits regardless of provincial scope expansion"]}, {"heading": "Natural Health Products (NHP) Regulation", "bullets": ["NPN (Natural Product Number) = licensed natural health product (vitamins, herbals, homeopathics) under NHP Regulations", "DIN (Drug Identification Number) = licensed conventional/pharmaceutical drug under Food and Drugs Act", "DIN-HM = homeopathic medicine with a DIN (older classification, being phased toward NPN)", "NHPs undergo lighter evidence review than DIN drugs — efficacy standards are lower", "Exam trap: NPN products can still interact with drugs (e.g., St. John's Wort induces CYP3A4) — 'natural' ≠ 'no interactions'"]}, {"heading": "Error Disclosure Duty", "bullets": ["Pharmacists have an ethical AND legal (in most provinces) duty to disclose medication errors to the patient", "Disclosure required even if the error caused no apparent harm", "Document the error via incident report / continuous quality improvement (CQI) process — separate from patient chart", "Apology and disclosure ≠ admission of legal liability in many provinces (apology legislation protects this)", "Failure to disclose is itself a professional misconduct/discipline risk, independent of the original error"]}, {"heading": "MAID (Medical Assistance in Dying) — Pharmacist Role", "bullets": ["Pharmacists may dispense MAID medications but are NOT required to personally administer them", "Conscientious objection is permitted — but objecting pharmacist must ensure timely referral/transfer of care, cannot abandon patient", "Pharmacist verifies eligibility documentation and prescription completeness before dispensing", "Extra vigilance on storage, transport, and unused medication return/destruction given lethality of MAID drugs", "MAID prescriptions require strict documentation per federal/provincial MAID legislation"]}, {"heading": "Classic Exam Traps", "bullets": ["Trap: thinking Schedule II means 'needs a prescription' — it means pharmacist-controlled access, not physician Rx", "Trap: assuming controlled substance prescriptions can be transferred like regular meds — generally prohibited", "Trap: believing pharmacist prescribing authority ever extends to narcotics/CDSA drugs — it never does", "Trap: confusing NPN and DIN — NPN is NOT proof of the same efficacy/safety standard as DIN", "Trap: thinking conscientious objection to MAID means no obligation at all — duty to refer/transfer still applies"]}]}, {"topic": "pk", "title": "Pharmacokinetics — High-Yield Review", "sections": [{"heading": "Half-Life & Steady State", "bullets": ["Steady state reached after ~4-5 half-lives, regardless of dose or infusion rate", "1 t1/2 = 50%, 2 = 75%, 3 = 87.5%, 4 = 93.75%, 5 = ~97% of steady state", "Time to steady state depends ONLY on half-life — not dose, not frequency", "Changing the dose changes the new steady-state concentration, not the time to reach it"]}, {"heading": "Loading Dose & Vd", "bullets": ["Loading Dose = Target Cp x Vd", "Used when time to steady state is too slow clinically (e.g., digoxin, phenytoin loading)", "Vd = Dose / Cp — apparent volume relating amount in body to plasma concentration", "Large Vd (e.g., digoxin ~500L) = extensive tissue distribution; small Vd = stays mostly in plasma (e.g., warfarin)", "Loading dose is NOT adjusted for renal/hepatic impairment — it's based on Vd, not clearance"]}, {"heading": "Clearance, Maintenance Dose, First-Pass", "bullets": ["Maintenance Dose = Css x Clearance x Dosing interval (rate in = rate out at steady state)", "Clearance is what's adjusted for renal/hepatic impairment — maintenance dose changes, loading dose doesn't", "First-pass metabolism: oral drugs absorbed via the portal vein pass through the liver before reaching systemic circulation, lowering bioavailability (F)", "High first-pass drugs have low oral bioavailability (e.g., propranolol, morphine) — may need much higher oral than IV doses"]}, {"heading": "Protein Binding", "bullets": ["Only unbound (free) drug is pharmacologically active and available for renal filtration/metabolism", "Highly protein-bound drugs (warfarin, phenytoin, valproic acid) — displacement or hypoalbuminemia raises free fraction/effect without necessarily changing total level", "Total levels can mislead in hypoalbuminemia — correct or interpret cautiously (e.g., Sheiner-Tozer for phenytoin)", "Acidic drugs bind albumin; basic drugs bind alpha-1-acid glycoprotein"]}, {"heading": "CYP450 Phenotype Concepts", "bullets": ["CYP2D6: activates codeine/tramadol/tamoxifen — ultrarapid metabolizers risk opioid toxicity, poor metabolizers get no benefit", "CYP2C19: activates clopidogrel (poor metabolizers = reduced antiplatelet effect); also metabolizes PPIs", "CYP2C9: metabolizes warfarin, phenytoin — poor metabolizers need lower doses, higher toxicity/bleeding risk", "Phenotypes: poor / intermediate / extensive (normal) / ultrarapid metabolizer", "Prodrugs (codeine, clopidogrel, tramadol) need enzyme activity for EFFECT; most drugs need it for CLEARANCE"]}, {"heading": "Zero-Order vs First-Order Kinetics", "bullets": ["First-order (most drugs): constant FRACTION eliminated per unit time; half-life stays constant", "Zero-order (phenytoin at high levels, alcohol, high-dose ASA): constant AMOUNT eliminated per unit time (enzyme saturation)", "In zero-order kinetics, small dose changes can cause disproportionately large concentration changes", "'Half-life' isn't a fixed, meaningful concept once kinetics become zero-order"]}, {"heading": "TDM Target Ranges to Memorize", "bullets": ["Digoxin: 0.5-2.0 ng/mL (HF target lower end ~0.5-0.9)", "Lithium: 0.6-1.2 mmol/L (maintenance), trough drawn 12h post-dose", "Phenytoin: 10-20 mg/L total (free 1-2 mg/L)", "Vancomycin: AUC24/MIC ≥400 (modern target); trough 15-20 mg/L if used", "Theophylline: 10-20 mcg/mL (some target 5-15)", "Carbamazepine 4-12 mg/L; Valproic acid 50-100 mg/L"]}, {"heading": "Exam-Trap Pearls", "bullets": ["Loading dose → based on Vd; Maintenance dose → based on clearance — don't mix these up", "Time to steady state depends only on half-life — a classic trap answer says dose changes it", "Trough levels reflect toxicity/accumulation; peak levels reflect efficacy (esp. aminoglycosides)", "Draw digoxin levels ≥6-8h post-dose to avoid the distribution phase (falsely high early level)", "Hepatic impairment mainly affects clearance/first-pass; renal impairment mainly affects clearance of renally-eliminated drugs/active metabolites"]}]}, {"topic": "inter", "title": "Drug Interactions — High-Yield Review", "sections": [{"heading": "CYP450 Inhibitors to Memorize", "bullets": ["Strong CYP3A4 inhibitors: azole antifungals (ketoconazole, itraconazole, fluconazole), macrolides (clarithromycin, erythromycin — not azithromycin), protease inhibitors, grapefruit juice", "Broad/multi-CYP inhibitors: cimetidine, amiodarone", "CYP2C9 inhibitors: fluconazole, amiodarone, metronidazole — raise warfarin/phenytoin levels", "CYP2D6 inhibitors: fluoxetine, paroxetine, bupropion — reduce codeine/tamoxifen/tramadol activation", "Inhibition onset is typically fast (days) — faster than induction"]}, {"heading": "CYP450 Inducers to Memorize", "bullets": ["Classic inducers: Rifampin, Carbamazepine, Phenytoin, Phenobarbital, St. John's Wort (chronic alcohol/smoking also induce select pathways)", "Inducers take 1-2 weeks to develop full effect and 1-2 weeks to resolve after stopping", "Effect: reduce levels/efficacy of CYP substrates (OCs, warfarin, cyclosporine, tacrolimus)", "Classic exam trap: starting an inducer can cause treatment failure or breakthrough bleeding weeks into therapy, not immediately"]}, {"heading": "Serotonin Syndrome Combinations", "bullets": ["Triggers: MAOIs + SSRIs/SNRIs/tramadol/meperidine/triptans/linezolid/St. John's Wort", "Triad: mental status change (agitation), autonomic instability (tachycardia, hyperthermia, diaphoresis), neuromuscular signs (tremor, clonus, hyperreflexia)", "Meperidine + MAOI is a classic, potentially fatal, absolute contraindication", "Washout periods required around MAOIs (e.g., 2 weeks off MAOI before an SSRI; 5 weeks off fluoxetine before an MAOI)"]}, {"heading": "QT-Prolonging Combinations", "bullets": ["Classic QT drugs: amiodarone, macrolides, fluoroquinolones, antipsychotics (haloperidol, quetiapine), ondansetron, methadone", "Combining 2+ QT-prolonging drugs has additive/synergistic torsades de pointes risk", "Hypokalemia/hypomagnesemia (e.g., from diuretics) potentiate QT-related arrhythmia risk", "Consider baseline/ongoing ECG when stacking QT-prolonging drugs in higher-risk patients"]}, {"heading": "Bleeding-Risk Combinations", "bullets": ["Warfarin/DOACs + NSAIDs/ASA/clopidogrel = additive pharmacodynamic bleeding risk (not a PK interaction)", "Warfarin + CYP2C9 inhibitors (fluconazole, amiodarone, metronidazole, TMP-SMX) = pharmacokinetic rise in INR", "SSRIs alone raise bleeding risk (impaired platelet serotonin uptake) — additive with anticoagulants/NSAIDs", "Broad-spectrum antibiotics can raise INR by reducing vitamin K-producing gut flora"]}, {"heading": "'Triple Whammy' & Renal-Risk Combos", "bullets": ["Triple whammy = ACEI/ARB + diuretic + NSAID → acute kidney injury risk (reduced renal perfusion/autoregulation)", "Each drug reduces renal blood flow/filtration by a different mechanism — combined effect is synergistic", "Counsel patients on ACEI/ARB + diuretic to avoid OTC NSAIDs", "Combining nephrotoxic drugs (aminoglycosides, vancomycin, contrast dye, NSAIDs) compounds AKI risk"]}, {"heading": "Absorption / Chelation Interactions", "bullets": ["Divalent/trivalent cations (Ca, Mg, Al, Fe, Zn) chelate fluoroquinolones and tetracyclines — separate by 2h before/4-6h after", "Antacids/dairy/mineral supplements reduce absorption of affected antibiotics and levothyroxine", "Levothyroxine also affected by calcium, iron, and PPIs — take on an empty stomach, separated from interacting products", "Bile acid resins (cholestyramine) can bind and reduce absorption of many co-administered drugs — separate dosing"]}, {"heading": "P-glycoprotein (P-gp) Interactions", "bullets": ["P-gp is an efflux transporter (gut, kidney, BBB, liver) affecting absorption/elimination independent of CYP metabolism", "Digoxin is the classic P-gp substrate with a narrow TI — inhibitors (amiodarone, verapamil, clarithromycin, quinidine) raise levels", "P-gp inducers (rifampin, St. John's Wort) lower digoxin levels", "Cyclosporine/tacrolimus are both CYP3A4 AND P-gp substrates — overlapping interaction risk with azoles/macrolides"]}, {"heading": "Exam-Trap Pearls", "bullets": ["Not all interactions are enzyme-based — pharmacodynamic (additive-effect) interactions matter just as much", "Azithromycin is the 'safe' macrolide for CYP3A4 interactions — a common distractor vs. clarithromycin/erythromycin", "A single dose of an inhibitor (e.g., one dose of fluconazole) can still meaningfully interact due to long half-lives", "Grapefruit juice affects intestinal, not hepatic, CYP3A4 — explains why IV drugs are unaffected", "Herbal products (St. John's Wort) often go undisclosed by patients — always ask specifically"]}]}, {"topic": "peds", "title": "Pediatrics — High-Yield Review", "sections": [{"heading": "Weight-Based Dosing Rules", "bullets": ["Always dose by actual body weight (mg/kg), not by age brackets — age charts are approximations only", "Double-check units: mg/kg/DOSE vs mg/kg/DAY — a classic MCQ trap that changes the answer 3-4x", "Convert lb to kg first (divide by 2.2) before any calculation", "Cap pediatric doses at the adult max dose when weight-based calc would exceed it (common in obese/larger children)", "Use calibrated oral syringes/dosing devices, never household spoons"]}, {"heading": "Age-Restricted OTC/Rx Products", "bullets": ["ASA contraindicated in children/teens with viral illness — Reye syndrome risk", "Cough/cold combination products not recommended under 6 years (many withdrawn under 6 in Canada)", "Ibuprofen contraindicated under 6 months of age", "Codeine contraindicated in children <12 years and in breastfeeding (CYP2D6 ultra-rapid metabolizer risk of morphine toxicity)", "Diphenhydramine-based sleep aids not recommended in young children — paradoxical excitation risk"]}, {"heading": "Common Calculation Traps", "bullets": ["Confusing the drug's concentration (e.g., 160 mg/5 mL vs 80 mg/2.5 mL) — always read label concentration, don't assume", "Forgetting to convert mg to mL using the actual product concentration given in the stem", "Using ideal body weight vs actual weight when the question specifies one or the other", "Missing that some max daily doses are capped independent of weight (e.g., acetaminophen daily max)", "Rounding errors — round to a measurable/practical volume on an oral syringe"]}, {"heading": "Vaccination Catch-Up Basics", "bullets": ["Minor illness without fever is NOT a contraindication to vaccination — true contraindications are anaphylaxis to a prior dose/component or specific live-vaccine immunosuppression concerns", "Live vaccines (MMR, varicella) can be given same day or must be spaced ≥4 weeks apart if not simultaneous", "Catch-up schedules follow NACI/provincial guidance — minimum intervals between doses matter more than exact age", "Prophylactic antipyretics before vaccination are generally NOT recommended (may blunt immune response)", "Pharmacists play a key role in identifying gaps and non-judgmental vaccine hesitancy counselling"]}, {"heading": "Pediatric Asthma Devices", "bullets": ["Spacer (+/- mask for young children) is standard of care — dramatically improves MDI lung deposition", "Rescue (SABA e.g. salbutamol) is PRN only; controller (ICS e.g. fluticasone) must be used daily even when well", "Rinse mouth after ICS use to prevent thrush; not needed after SABA", "Needing reliever >2x/week signals poor control and need for step-up therapy", "Age-appropriate device choice: spacer+mask for infants/toddlers, spacer+mouthpiece for older children, dry powder inhalers generally not until child can generate adequate inspiratory flow (~school age)"]}, {"heading": "Red Flags Requiring Referral", "bullets": ["Fever in infant <3 months of age — always urgent medical referral", "Signs of dehydration: no tears, dry mouth, sunken fontanelle, reduced wet diapers, lethargy", "High fever >3 days duration, or any fever with stiff neck/rash/lethargy", "Difficulty breathing, stridor, or retractions", "Any suspected poisoning/overdose (e.g., iron, acetaminophen) — immediate poison control/ED referral"]}, {"heading": "Exam-Trap Pearls", "bullets": ["Amoxicillin rash in a child with concurrent mononucleosis is a non-allergic reaction, not a true penicillin allergy", "High-dose amoxicillin (80-90 mg/kg/day) is used for AOM specifically to overcome resistant S. pneumoniae — don't pick standard-dose in that scenario", "ORS is preferred over sports drinks/juice for rehydration — osmolarity/electrolyte ratio matters", "Iron overdose is a leading cause of accidental pediatric poisoning death — always counsel on safe storage", "Stimulant ADHD medications require baseline and periodic growth/cardiovascular monitoring, not just symptom tracking"]}]}, {"topic": "geri", "title": "Geriatrics & Palliative Care — High-Yield Review", "sections": [{"heading": "Beers Criteria Highlights", "bullets": ["Avoid benzodiazepines and Z-drugs (zopiclone) in older adults — falls, fractures, cognitive impairment", "Avoid strong anticholinergics (oxybutynin, diphenhydramine, tertiary TCAs like amitriptyline) — delirium, falls, constipation, urinary retention", "Avoid glyburide specifically among sulfonylureas — prolonged, severe hypoglycemia risk in elderly", "Antipsychotics carry boxed warning for increased mortality in dementia-related psychosis — lowest dose, shortest duration", "Digoxin doses >0.125 mg/day generally avoided — narrow therapeutic index, reduced renal clearance with age"]}, {"heading": "STOPP/START Tools", "bullets": ["STOPP = Screening Tool of Older Persons' Prescriptions — flags potentially inappropriate medications to STOP", "START = Screening Tool to Alert to Right Treatment — flags indicated therapies that may be missing (e.g., START a bone protection agent in osteoporosis)", "STOPP flags benzodiazepine use ≥4 weeks in patients with a falls history", "Both tools are used together in comprehensive geriatric medication review, not just deprescribing", "Complement, don't replace, clinical judgment — patient goals of care take priority near end of life"]}, {"heading": "Deprescribing Principles", "bullets": ["Review indication for every drug — is it still needed, was it started for a now-resolved issue?", "Taper rather than stop abruptly for drugs with withdrawal/rebound risk (benzodiazepines, opioids, corticosteroids, PPIs)", "Prioritize deprescribing drugs with the highest harm-to-benefit ratio in the current context (e.g., statins in very limited life expectancy)", "Watch for prescribing cascades — a new drug started to treat a side effect of another drug (e.g., anticholinergic causing constipation treated with more medication instead of addressing the cause)", "Involve patient/family in shared decision-making, especially reframing goals near end of life (comfort vs prevention)"]}, {"heading": "Anticholinergic Burden", "bullets": ["Cumulative effect matters — multiple mild anticholinergics can add up to high total burden (ACB scale)", "Classic culprits: oxybutynin, diphenhydramine, amitriptyline, some antipsychotics, some antiemetics", "Signs: dry mouth, constipation, urinary retention, blurred vision, confusion/delirium, falls", "Higher burden associated with long-term cognitive decline risk in observational studies", "Prefer lower-burden alternatives: mirabegron over oxybutynin, second-gen antihistamines over diphenhydramine, nortriptyline over amitriptyline if a TCA is truly needed"]}, {"heading": "Palliative Symptom Management Basics", "bullets": ["Low-dose opioids are first-line for refractory dyspnea, not just pain — key distinguishing palliative concept", "Always co-prescribe a stimulant laxative (e.g., senna) prophylactically with regular opioids — constipation does not resolve with tolerance", "Glycopyrrolate (or scopolamine) is used for terminal secretions ('death rattle') — start early, as it prevents new secretions but doesn't clear existing ones", "Haloperidol (low dose) is used for palliative nausea and for severe delirium-related agitation after non-pharm measures fail", "Dexamethasone serves multiple overlapping palliative roles: appetite stimulation, reducing mass-effect pain/edema, mood/energy — comfort-focused risk/benefit differs from long-term use"]}, {"heading": "Renal & Hepatic Adjustments in Elderly", "bullets": ["Renal function (via Cockcroft-Gault, using actual body weight generally) commonly declines with age even with normal serum creatinine — always calculate CrCl, don't rely on creatinine alone", "Morphine's active metabolite (M6G) accumulates in renal impairment — consider hydromorphone or fentanyl as alternatives", "Digoxin, gabapentin, and many antibiotics need renal dose adjustment in elderly", "Reduced hepatic first-pass metabolism and lower muscle mass alter volume of distribution — 'start low, go slow' applies broadly", "Reassess renal/hepatic function periodically, not just at treatment initiation, as it can decline further with acute illness/dehydration"]}, {"heading": "Exam-Trap Pearls", "bullets": ["A drug being available 'over-the-counter' does not mean it is safe in the elderly — diphenhydramine is a top Beers-flagged OTC offender", "Sedation plus orthostatic hypotension (e.g., from a TCA) is a classic combination tested as a falls-risk scenario", "Hypoglycemia in an elderly patient can present as confusion or a fall rather than classic sweating/shakiness — consider it in atypical presentations", "'Comfort care' / palliative goals can justify continuing or stopping medications that would otherwise follow standard chronic-disease guidelines (e.g., stopping statins, continuing opioids liberally)", "Glycopyrrolate is preferred over scopolamine when less sedation/delirium risk is desired, because it doesn't cross the blood-brain barrier"]}]}, {"topic": "onc", "title": "Oncology & Hematology — High-Yield Review", "sections": [{"heading": "Chemo Safety Handling Basics", "bullets": ["Hazardous drugs require PPE: chemo gloves (double-gloved), gown, eye protection when compounding/administering", "Use a biological safety cabinet (Class II) or isolator for compounding; never compound hazardous drugs on an open bench", "Spill kits must be readily available wherever hazardous drugs are stored/prepared/administered", "Closed-system transfer devices (CSTDs) reduce aerosolization/exposure risk during preparation and administration", "Pregnant/breastfeeding staff should avoid handling hazardous drugs per workplace policy", "Dispose of chemo waste in designated cytotoxic waste containers, not regular sharps/trash"]}, {"heading": "Emetogenicity Risk Tiers & Prophylaxis", "bullets": ["High emetic risk (e.g., cisplatin, AC combo): 5-HT3 antagonist + NK1 antagonist + dexamethasone (+/- olanzapine)", "Moderate risk (e.g., carboplatin, oxaliplatin): 5-HT3 antagonist + dexamethasone (+/- NK1 antagonist)", "Low risk (e.g., paclitaxel, gemcitabine): single agent, e.g., dexamethasone or 5-HT3 antagonist alone", "Minimal risk (e.g., vincristine, bleomycin): no routine prophylaxis needed", "Delayed CINV (24h-5 days post-chemo) needs ongoing coverage — dexamethasone/NK1 antagonist continued, not just acute-phase ondansetron", "Anticipatory nausea is best prevented, not treated — consider lorazepam adjunct for anxious patients with prior bad experience"]}, {"heading": "Myelosuppression & Neutropenic Fever Red Flags", "bullets": ["Nadir (lowest blood counts) typically occurs 7-14 days post-chemo — highest infection risk window", "Febrile neutropenia = single temp >=38.3C (or >=38.0C sustained 1h) PLUS ANC <0.5x10^9/L (or <1.0 trending down) — this is a MEDICAL EMERGENCY", "Febrile neutropenia requires immediate empiric broad-spectrum IV antibiotics — do not wait for culture results", "Counsel patients to seek immediate care for fever during nadir period, avoid crowds/sick contacts, and practice hand hygiene", "G-CSF (filgrastim) primary prophylaxis considered when regimen carries >20% febrile neutropenia risk", "Avoid NSAIDs/antipyretics that could mask fever in at-risk neutropenic patients without medical guidance"]}, {"heading": "Extravasation Risk Drugs", "bullets": ["Vesicants (severe tissue damage if extravasated): doxorubicin, vincristine, vinblastine, mitomycin, dactinomycin", "Irritants (less severe but still concerning): oxaliplatin, carboplatin, etoposide", "Anthracycline extravasation: STOP infusion, aspirate, apply cold compress, consider dexrazoxane antidote", "Vinca alkaloid extravasation: apply WARM compress (opposite of anthracyclines) — classic exam contrast point", "Early signs: pain, burning, swelling, redness at IV site during infusion — stop immediately and assess"]}, {"heading": "Cancer-Associated Thrombosis (CAT) Anticoagulation", "bullets": ["Cancer patients have markedly elevated VTE risk (Trousseau's syndrome) from tumor procoagulant factors", "LMWH (e.g., dalteparin) historically preferred over warfarin — better efficacy, avoids interaction complexity with chemo/nutrition", "DOACs (apixaban, rivaroxaban) now guideline-supported alternatives EXCEPT in GI/GU luminal malignancies (higher bleeding risk)", "Warfarin is generally avoided as first-line in active cancer due to unpredictable INR control with chemo interactions/nutritional changes", "Duration of anticoagulation is typically extended (often indefinite) while cancer remains active, unlike standard provoked VTE"]}, {"heading": "Classic Exam-Trap Pearls", "bullets": ["Vincristine is FATAL if given intrathecally — IV administration only, always double-check route", "Weekly low-dose oral methotrexate (RA) mistakenly given DAILY has caused fatal overdoses — verify frequency", "Leucovorin (folinic acid, MTX rescue) vs leuprolide (GnRH agonist) — sound-alike names, very different drugs", "G-CSF should NOT be given within 24h before/after cytotoxic chemo — timing error worsens marrow toxicity", "Anthracyclines: cold compress for extravasation; Vinca alkaloids: warm compress — do not mix these up"]}]}, {"topic": "immun", "title": "Immunizations & Travel Health — High-Yield Review", "sections": [{"heading": "NACI Schedule Highlights — Childhood", "bullets": ["Routine series starts at 2 months: DTaP-IPV-Hib, pneumococcal conjugate (PCV), rotavirus", "MMR: first dose at 12 months, second dose per province (commonly 18 months or 4-6 years)", "Varicella vaccine typically given around 12-18 months, second dose in childhood", "Meningococcal conjugate given in infancy and boosted in adolescence", "HPV vaccine typically offered around grade 6-7 (age 9-12), 2-dose schedule if started before age 15"]}, {"heading": "NACI Schedule Highlights — Adult & Senior", "bullets": ["Td/Tdap booster every 10 years; at least one adult dose should be Tdap to maintain pertussis coverage", "Influenza vaccine annually for all adults 6 months+; high-dose/adjuvanted formulations preferred for 65+", "Shingrix (recombinant zoster) recommended starting age 50, 2-dose series 2-6 months apart", "Pneumococcal vaccination (PCV +/- PPSV23) recommended for 65+ or high-risk chronic conditions", "RSV vaccine recommended for adults 60+, particularly those with chronic cardiopulmonary conditions", "Tdap recommended in every pregnancy, ideally 27-32 weeks gestation, for passive newborn protection"]}, {"heading": "Live vs Inactivated Vaccines — Contraindications", "bullets": ["Live vaccines (MMR, varicella, live zoster [old], oral typhoid, yellow fever, FluMist, rotavirus) contraindicated in pregnancy and significant immunocompromise", "Inactivated/recombinant vaccines (flu shot, Tdap, HPV, hepatitis A/B, Shingrix, pneumococcal) are safe in pregnancy and immunocompromised patients", "Two live vaccines given on different days must be spaced >=4 weeks apart; no spacing needed if given same day", "No spacing restriction needed between a live and an inactivated vaccine given on different days", "Antibody-containing blood products can blunt live vaccine response — spacing (weeks-months) required before/after MMR/varicella depending on product"]}, {"heading": "Cold Chain Basics", "bullets": ["Most vaccines require storage at 2-8C (refrigerator) — monitor with a calibrated thermometer/data logger", "Never freeze vaccines that require refrigeration (e.g., most inactivated vaccines) — freezing destroys efficacy", "Some products (e.g., certain mRNA vaccines) require ultra-cold or freezer storage — check product monograph", "Have a cold-chain break protocol: quarantine affected vaccines, do not use/discard until manufacturer/public health confirms viability", "Transport vaccines in insulated coolers with appropriate cold packs and monitor temperature during transit"]}, {"heading": "Travel Vaccine Categories", "bullets": ["Routine: ensure standard schedule (MMR, Tdap, flu) is up to date regardless of destination", "Recommended: risk-based on destination/activity — hepatitis A/B, typhoid, rabies, Japanese encephalitis", "Required: legally mandated for entry — yellow fever (IHR-regulated countries), meningococcal ACWY (Hajj/Umrah)", "Yellow fever vaccine must be given at a designated Yellow Fever Vaccination Centre; certificate valid 10 days after dose", "Malaria prevention is chemoprophylaxis (not a vaccine) — separate counselling on antimalarials plus bite prevention"]}, {"heading": "Classic Exam-Trap Pearls", "bullets": ["Egg allergy is NOT a contraindication to standard-dose influenza or MMR vaccines — outdated teaching still shows up as a distractor", "MenACWY is legally REQUIRED for Hajj/Umrah travel, not just recommended — distinct from most other travel vaccines", "Yellow fever vaccine can only be administered at designated centres in Canada — cannot be given at any random pharmacy", "Conjugate (PCV) vaccines must be given BEFORE polysaccharide (PPSV23) when both are indicated, to optimize immune priming", "Passive maternal immunization (Tdap, RSV/Abrysvo in pregnancy) protects the newborn before their own vaccine series can start — same underlying concept, two different diseases"]}]}, {"topic": "derm", "title": "Dermatology, Eye & ENT — High-Yield Review", "sections": [{"heading": "Topical Corticosteroid Potency Ladder", "bullets": ["7 potency groups in Canada: I = super-high potency (clobetasol) down to VII = low (hydrocortisone 0.5-1%)", "Face, groin, axillae, eyelids = LOW potency only (thin skin, high absorption)", "Palms/soles/thick plaques = higher potency often needed for penetration", "Occlusion (diapers, dressings) increases potency/absorption — adjust choice accordingly", "Long-term high-potency use risk: atrophy, striae, telangiectasia, HPA-axis suppression", "EXAM TRAP: 'just use the strongest one' is wrong — potency must match site and severity"]}, {"heading": "Acne Treatment Ladder", "bullets": ["Mild comedonal: topical retinoid (tretinoin/adapalene) ± benzoyl peroxide", "Mild-moderate inflammatory: add topical antibiotic (clindamycin) WITH benzoyl peroxide (never topical antibiotic alone — resistance)", "Moderate-severe: add oral antibiotic (doxycycline/minocycline) for limited duration, or consider hormonal therapy (females)", "Severe/nodulocystic/scarring: oral isotretinoin (specialist-initiated, pregnancy prevention program mandatory)", "BPO + tretinoin = do NOT mix simultaneously (BPO oxidizes/inactivates tretinoin) — use adapalene instead or stagger AM/PM", "EXAM TRAP: benzoyl peroxide prevents antibiotic resistance — always pair topical/oral antibiotics with BPO"]}, {"heading": "Glaucoma Drop Classes", "bullets": ["Prostaglandin analogues (latanoprost) — increase uveoscleral outflow, once daily HS, first-line; causes iris/lash pigmentation", "Beta-blockers (timolol) — decrease aqueous production; avoid in asthma/COPD/bradycardia/heart block (systemic absorption via nasolacrimal duct)", "Alpha-2 agonists (brimonidine) — decrease production + increase outflow; avoid in young children (CNS depression risk)", "Carbonic anhydrase inhibitors (dorzolamide) — decrease aqueous production; sulfa-related, caution with sulfa allergy", "EXAM TRAP: punctal occlusion after ANY eye drop reduces systemic absorption — critical for timolol to avoid systemic beta-blockade"]}, {"heading": "Eye Drop Administration Technique", "bullets": ["Wash hands, tilt head back, pull down lower lid to form pocket, instill drop without touching tip to eye", "Space multiple drops at least 5 minutes apart to prevent washout/dilution", "Apply punctal occlusion (press inner corner) for 1-2 minutes to reduce systemic absorption", "Ointments go in after drops (thicker, blurs vision) — use gtts before ung", "Remove contact lenses before most drops; wait 15 min before reinsertion (check product-specific advice)"]}, {"heading": "Otic Drops — Key Points", "bullets": ["Otitis externa: acidifying/antibiotic ± steroid drops (e.g., ciprofloxacin/dexamethasone)", "Warm drops before use — cold drops can trigger vertigo/dizziness (caloric reflex)", "AVOID aminoglycosides (neomycin, gentamicin) if tympanic membrane perforation is suspected — ototoxicity risk", "Fluoroquinolone-based otic combos (e.g., Ciprodex) are safe even with perforated TM/tubes", "Lie with affected ear up for 1-2 minutes after instillation for contact time"]}, {"heading": "Red Flags — Eye Complaints Needing Referral", "bullets": ["Sudden vision loss or significant vision change", "Severe eye pain, photophobia with pain (possible uveitis/keratitis)", "Trauma, chemical exposure, or foreign body sensation", "Contact lens wearer with pain + redness (risk of microbial keratitis — urgent)", "Unequal pupils, halos around lights + severe pain (possible acute angle-closure glaucoma — emergency)"]}, {"heading": "Red Flags — Ear/Nose Complaints Needing Referral", "bullets": ["Hearing loss, severe pain, or bleeding from the ear", "Suspected tympanic membrane perforation with drainage", "Persistent nosebleeds not controlled with basic first aid, or recurrent epistaxis", "Signs of mastoiditis (swelling/redness behind ear, fever) — emergency", "Nasal symptoms with high fever, facial swelling, or vision changes (possible orbital cellulitis)"]}, {"heading": "Classic Exam-Trap Pearls", "bullets": ["Tretinoin + benzoyl peroxide together = tretinoin gets oxidized/inactivated — stagger dosing or switch to adapalene", "Latanoprost causes PERMANENT iris/lash pigmentation changes — must counsel proactively, not just list as a side effect", "Aminoglycoside otic drops (neomycin) are ototoxic if the eardrum is perforated — Ciprodex is the safe alternative", "Nasal corticosteroids need DAYS of regular use for full effect — not a PRN rescue med like decongestant sprays", "Punctal occlusion reduces systemic absorption/side effects for ALL eye drops, especially important for timolol (beta-blocker) systemic effects"]}]}, {"topic": "otc", "title": "OTC & Natural Health Products — High-Yield Review", "sections": [{"heading": "Self-Care Triage Frameworks", "bullets": ["WWHAM: Who is it for? What are the symptoms? How long? Action already taken? Medications currently taken?", "ASMETHOD: Age/appearance, Self or someone else, Medications, Extra symptoms, Time/duration, History, Danger symptoms, Other diagnoses", "Always confirm the patient isn't self-treating something that needs a diagnosis (e.g., chest pain as 'heartburn')", "Duration matters: symptoms persisting beyond typical self-limiting window (e.g., >1-2 weeks) = refer"]}, {"heading": "Red Flags Requiring Referral (General)", "bullets": ["GI: rectal bleeding, black/tarry stools, unintended weight loss, dysphagia, persistent vomiting", "Pain: severe/unexplained pain, chest pain, pain not responding to appropriate OTC treatment", "Fever: high fever, fever >3 days, fever in infants <3 months (always refer)", "Any symptom in infants, pregnant/breastfeeding patients, or immunocompromised needs lower threshold for referral", "Symptoms recurring frequently or worsening despite appropriate self-treatment"]}, {"heading": "Classic NHP-Drug Interactions", "bullets": ["St. John's Wort — potent CYP3A4/P-gp INDUCER: reduces efficacy of OCPs, warfarin, cyclosporine, many antidepressants; serotonin syndrome risk with SSRIs/SNRIs/triptans", "Ginkgo biloba — increases bleeding risk with warfarin, DOACs, ASA, NSAIDs; stop 1-2 weeks pre-surgery", "Fish oil (high dose >3g/day) — antiplatelet effect, caution with anticoagulants", "Glucosamine — shellfish-derived (allergy caution), theoretical mild blood glucose increase", "Vitamin K-containing supplements — antagonize warfarin effect (INR destabilization)", "Calcium/iron/antacids — chelate and reduce absorption of levothyroxine, tetracyclines, fluoroquinolones — separate by 2+ hours"]}, {"heading": "Age Restrictions on OTC Products", "bullets": ["ASA — avoid in children/teens with viral illness (Reye's syndrome risk)", "Cough/cold combination products — not recommended under 6 years in Canada; caution/avoid under 12 per current guidance", "Diphenhydramine/first-gen antihistamines — caution in elderly (anticholinergic burden, falls, confusion — Beers Criteria) and avoid as routine sleep aid long-term", "Codeine-containing OTC products — restricted/prescription-only for those under 18 in most Canadian jurisdictions now", "Decongestants (pseudoephedrine/phenylephrine) — caution in hypertension, and behind-counter sales due to methamphetamine precursor control"]}, {"heading": "Antacid vs H2RA vs PPI — Onset/Duration", "bullets": ["Antacids (calcium carbonate) — fastest onset (minutes), shortest duration (20-60 min)", "H2RAs (famotidine) — onset ~1 hour, duration 10-12 hours; good for prevention before trigger meals", "PPIs (omeprazole OTC) — slower onset (1-4 days for full effect), longest duration; best for frequent/regular heartburn (>2x/week)", "Separate antacids from other oral meds by 2+ hours (absorption interference)"]}, {"heading": "Laxative Selection", "bullets": ["Bulk-forming (psyllium) — first-line, needs adequate fluid intake, slow onset (days)", "Osmotic (PEG 3350) — safe for long-term/chronic use, onset 1-3 days, minimal electrolyte disturbance", "Stimulant (senna, bisacodyl) — short-term use, onset 6-12 hours, more cramping, avoid chronic daily use", "Stool softener (docusate) — prevention of straining, not a true laxative, mild effect only"]}, {"heading": "Sleep Aids & Smoking Cessation Quick Points", "bullets": ["Melatonin — low dose (0.5-3mg) 30-60 min before bed; timing > dose for jet lag", "Diphenhydramine/doxylamine — short-term only, tolerance develops in days, avoid in elderly", "NRT — match product to need: patch = steady background, gum/lozenge/inhaler = breakthrough cravings; combination therapy often superior", "NRT gum — 'chew and park' technique; avoid acidic beverages 15 min before/during use (reduces absorption)"]}, {"heading": "Classic Exam-Trap Pearls", "bullets": ["St. John's Wort can make hormonal birth control FAIL — always ask about OCP use before recommending", "Ginkgo + warfarin/ASA/NSAIDs = bleeding risk — a favourite interaction question", "Iron supplements turn stool black (benign) — don't confuse with melena, but always clarify with patient history", "Antacids/calcium/iron block absorption of levothyroxine and fluoroquinolones — timing separation is the tested answer", "PPI vs H2RA vs antacid onset/duration ranking is frequently tested — antacid fastest/shortest, PPI slowest/longest"]}]}, {"topic": "ethics", "title": "Ethics & Professional Practice — High-Yield Review", "sections": [{"heading": "Four Core Principles", "bullets": ["Autonomy — respect a capable patient's right to decide, even to refuse treatment", "Beneficence — act in the patient's best interest", "Non-maleficence — 'first, do no harm'; prevent harm from errors/interactions", "Justice — fair, equitable treatment regardless of who the patient is", "Exam trap: no single principle is absolute — weigh in context, don't default to paternalism"]}, {"heading": "Informed Consent", "bullets": ["Elements: capacity + voluntariness + disclosure of material info + comprehension", "Consent is ongoing — can be withdrawn any time", "Emergency exception: implied consent if incapable, no SDM available, delay = harm", "Teach-back confirms real understanding, not just a signature"]}, {"heading": "Confidentiality & Exceptions", "bullets": ["Default: no disclosure without consent", "Exceptions: imminent serious harm to self/others, mandatory reporting (e.g., certain diseases, child abuse), court order, college inspection", "Family members are NOT automatically entitled to info — confirm consent/SDM status first", "Circle of care allows sharing among treating providers, but patient can 'lock box' specific info"]}, {"heading": "Conscientious Objection", "bullets": ["May decline personally on moral grounds, but must NOT abandon the patient", "Must give timely, effective referral (not vague 'try elsewhere')", "No lecturing/moralizing to the patient", "In a true emergency with no alternative, most colleges require providing the service anyway"]}, {"heading": "Error Disclosure", "bullets": ["Disclose to patient promptly and honestly — separate duty from internal CQI/incident reporting", "Disclose even if no harm occurred or patient hasn't noticed", "Apologize sincerely; explain corrective steps", "Silence or delay is itself an ethical breach"]}, {"heading": "Capacity & SDM", "bullets": ["Capacity is decision-specific and time-specific, not global", "Disagreeing with pharmacist advice ≠ incapacity", "SDM hierarchy (varies by province): guardian > attorney for personal care > spouse > child > parent > sibling", "Reassess capacity once a temporary condition (intoxication, delirium) resolves, if decision is non-urgent"]}, {"heading": "Scope of Practice & Conflicts of Interest", "bullets": ["Practicing beyond authorized scope = regulatory violation even if clinically confident", "Refer when complexity exceeds scope", "Disclose financial/personal interests that could bias recommendations", "Some conflicts require avoidance, not just disclosure (e.g., dispensing to self)"]}, {"heading": "Non-Judgmental Care & Boundaries", "bullets": ["Use objective criteria (PMP checks) consistently for ALL patients — inconsistent scrutiny = discrimination", "Patients with substance use disorder still deserve dignified, non-stigmatizing care", "No dual/romantic relationships with patients — power imbalance always exists", "Cultural competence: ask, don't assume; use professional interpreters, not children"]}, {"heading": "Classic Exam-Trap Pearls", "bullets": ["Conscientious objection ≠ clinical judgment — don't confuse the two", "Duty-to-warn overrides confidentiality only for imminent, serious, identifiable-target harm", "'Apology' language is protected from being used as legal admission in most provinces", "Therapeutic privilege (withholding truth to protect the patient) is essentially never justified today", "Reporting a suspected impaired colleague is mandatory, not optional collegiality"]}]}, {"topic": "calc", "title": "Calculations & Compounding — High-Yield Review", "sections": [{"heading": "Renal Dosing — Cockcroft-Gault", "bullets": ["CrCl = [(140-age) x wt(kg)] / (72 x SCr mg/dL) x 0.85 if female", "Convert SCr from micromol/L to mg/dL by dividing by 88.4", "Use adjusted body weight if >30% over ideal body weight", "Don't forget the female correction factor — classic omission"]}, {"heading": "IV Flow Rates", "bullets": ["mL/hr = total volume / total time(hr)", "gtt/min = (volume mL x drop factor gtt/mL) / time(min) — convert hr to min first", "Macrodrip: 10/15/20 gtt/mL; Microdrip: 60 gtt/mL (peds/precision)", "Shortcut: with microdrip (60gtt/mL), gtt/min numerically = mL/hr"]}, {"heading": "Alligation & Dilution", "bullets": ["Grid: desired % in middle; higher stock top-left, lower stock (or 0) bottom-left", "Parts of higher = |desired-lower|; parts of lower = |higher-desired|", "Desired % must fall between the two stock %'s", "Verify with mass balance: (V1C1+V2C2)/Vtotal = desired conc"]}, {"heading": "BSA & Pediatric Dosing", "bullets": ["Mosteller BSA(m^2) = sqrt[(height cm x weight kg)/3600]", "Dose = BSA x dose/m^2 (chemo, some peds protocols)", "Peds: mg/kg/day ÷ doses/day = per-dose amount — don't confuse mg/kg/day with mg/kg/dose", "Always compare pediatric calculated dose to adult max ceiling"]}, {"heading": "Days Supply & Electrolytes", "bullets": ["Days supply = total qty dispensed / qty used per day", "Taper regimens: calculate phase-by-phase, then sum", "mEq = mmol x valence; Na+/K+ valence=1 (mEq=mmol), Ca2+/Mg2+ valence=2 (mEq=2x mmol)", "Watch salt-form MW vs elemental ion MW in electrolyte calcs"]}, {"heading": "Compounding — Aliquots & BUD", "bullets": ["Aliquot method used when needed drug qty < minimum weighable qty (~120mg on Class A balance)", "Aliquot: dilute to a convenient total, then take proportional portion containing target amount", "Non-sterile BUD (no stability data): water-containing = 14 days refrigerated; non-aqueous = lesser of 25% remaining expiry or 6 months", "Sterile BUD depends on risk level (immediate/low/medium/high) and storage temp — always shorter than non-sterile"]}, {"heading": "Osmolarity, Tonicity & % Strength", "bullets": ["Osmolarity(mOsm/L) = mmol/L x number of dissociated particles", "0.9% NaCl ≈ 308 mOsm/L (isotonic); CaCl2 dissociates into 3 particles — don't forget", "D5W is isotonic in the bag; acts hypotonic physiologically after dextrose is metabolized", "%w/v x10 = mg/mL; use %w/w for semisolids (creams/ointments), not w/v"]}, {"heading": "Loading/Maintenance Dose & Dimensional Analysis", "bullets": ["Loading dose = (target Cp x Vd)/F — independent of clearance", "Maintenance rate = (target Cp x Clearance)/F — depends on clearance, not Vd", "Renal/hepatic impairment: usually adjust maintenance dose, not loading dose", "Always write out units in a conversion chain and cancel diagonally to catch inversion errors"]}, {"heading": "Ratio Strength & TPN Calories", "bullets": ["Ratio strength 1:X = 1g/X mL; convert to %: (1/X)x100; convert to mg/mL: 1000/X", "Epinephrine 1:1000 = 1mg/mL (IM anaphylaxis); 1:10000 = 0.1mg/mL (IV arrest) — never confuse the two", "Dextrose = 3.4 kcal/g; 20% lipid emulsion ≈ 2 kcal/mL; amino acids = 4 kcal/g (usually excluded from non-protein calorie counts)", "Nitrogen(g) = protein(g)/6.25, used for nitrogen balance/TPN calculations"]}, {"heading": "Classic Exam-Trap Pearls", "bullets": ["Rounding too early in multi-step calcs compounds error — round only at the final step", "Confusing mg/kg/day with mg/kg/dose is one of the most common pediatric dosing errors", "Forgetting to convert lb→kg (÷2.2) before weight-based dosing", "Forgetting the female (x0.85) factor in Cockcroft-Gault", "Mixing up valence for divalent electrolytes (Ca2+, Mg2+) in mEq/mmol conversions"]}]}];
